import{_ as t,o as a,c as s,a5 as d}from"./chunks/framework.C588jwcu.js";const k=JSON.parse('{"title":"自定义对话框","description":"","frontmatter":{"title":"自定义对话框","order":4},"headers":[],"relativePath":"zh/latest/tutorial/develop/customize-the-dialogbox.md","filePath":"zh/latest/tutorial/develop/customize-the-dialogbox.md","lastUpdated":1785683504000}'),o={name:"zh/latest/tutorial/develop/customize-the-dialogbox.md"};function i(l,e,r,n,p,c){return a(),s("div",null,[...e[0]||(e[0]=[d(`<h1 id="自定义对话界面" tabindex="-1">自定义对话界面 <a class="header-anchor" href="#自定义对话界面" aria-label="Permalink to &quot;自定义对话界面&quot;">​</a></h1><h2 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h2><p>如果作品需要自定义对话界面，请先把选用的模板场景复制到项目自己的目录（例如 <code>res://ui/dialogue/</code>），再编辑副本或为它配置自定义主题。</p><p>不要直接修改 <code>res://addons/konado/</code> 中的文件；插件升级会替换插件目录。使用项目内副本后，可以正常升级 Konado。</p><h2 id="编辑模板文件" tabindex="-1">编辑模板文件 <a class="header-anchor" href="#编辑模板文件" aria-label="Permalink to &quot;编辑模板文件&quot;">​</a></h2><p><code>res://addons/konado/template/</code> 保存的是内置对话界面模板。复制所需的 <code>.tscn</code> 到项目目录，在自己的对话场景中实例化副本，并把其中的 <code>KND_DialogueBox</code> 节点分配给 <code>KND_DialogueManager</code> 的 <code>_konado_dialogue_box</code> 属性。</p><p>一般情况下请不要修改节点上的脚本，而是通过修改节点上的属性来达到自定义的效果。</p><h2 id="自定义音频进度显示" tabindex="-1">自定义音频进度显示 <a class="header-anchor" href="#自定义音频进度显示" aria-label="Permalink to &quot;自定义音频进度显示&quot;">​</a></h2><p>普通对话设置了配音标签，并且对应语音资源正在播放时，对话框右下角会显示音频播放进度。没有配音标签、没有找到语音资源，或语音播放结束后，进度显示会自动隐藏。</p><p>该功能默认开启。如果项目不需要显示语音进度，可以选中对话框节点 <code>KonadoDialogueBox</code>，在检查器中关闭 <code>show_voice_progress</code>。</p><p>音频进度显示是一个独立组件，默认场景位于：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>res://addons/konado/template/default/voice_progress_display.tscn</span></span></code></pre></div><p>如果只是修改进度条的颜色、圆角、尺寸或内部布局，优先复制并编辑这个场景。默认组件中包含：</p><table tabindex="0"><thead><tr><th>节点</th><th>作用</th></tr></thead><tbody><tr><td><code>VoiceProgressDisplay</code></td><td>音频进度显示组件根节点</td></tr><tr><td><code>VoiceProgressBar</code></td><td>实际显示进度的 <code>ProgressBar</code></td></tr></tbody></table><p>常见自定义位置：</p><table tabindex="0"><thead><tr><th>需求</th><th>修改位置</th></tr></thead><tbody><tr><td>修改进度条宽高</td><td><code>VoiceProgressDisplay.custom_minimum_size</code></td></tr><tr><td>修改背景颜色</td><td><code>VoiceProgressBar</code> 的 <code>background</code> StyleBox</td></tr><tr><td>修改进度颜色</td><td><code>VoiceProgressBar</code> 的 <code>fill</code> StyleBox</td></tr><tr><td>修改圆角</td><td><code>background</code> 和 <code>fill</code> StyleBox 的 <code>corner_radius_*</code></td></tr><tr><td>改成更复杂的显示样式</td><td>在 <code>voice_progress_display.tscn</code> 中替换或增加子节点</td></tr></tbody></table><p>如果要调整进度显示在对话框中的位置，请在项目副本中编辑对应对话框模板里的 <code>VoiceProgressDisplay</code> 实例。内置源模板包括：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>res://addons/konado/template/default/knd_dialogue_box.tscn</span></span>
<span class="line"><span>res://addons/konado/template/custom_middle/konado_dialogue_middle.tscn</span></span></code></pre></div><p>组件脚本通过两个方法接收对话框传入的状态：</p><div class="language-gdscript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gdscript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> set_progress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(current: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, total: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> void</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> hide_progress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> void</span></span></code></pre></div><p>如果你想完全替换显示方式，可以保留这两个方法的含义：<code>set_progress()</code> 用于接收当前播放时间和总时长，<code>hide_progress()</code> 用于在没有配音或播放结束时隐藏组件。</p>`,21)])])}const g=t(o,[["render",i]]);export{k as __pageData,g as default};
